const item = items[0].json;

const text = String(
  item.message_text ||
  item.client_message ||
  item.user_message ||
  item.property_last_whats_app_message ||
  item.property_last_whatsapp_message ||
  item.last_message ||
  item.message ||
  ''
).toLowerCase().trim();

// "كم" (how much) must be its own word — otherwise it matches inside unrelated
// words like "عليكم" (as in "السلام عليكم"), which previously misfired as a
// pricing question and skipped the greeting/welcome flow entirely.
const hasStandaloneKam = /(^|[^ء-ي])كم([^ء-ي]|$)/.test(text);

// A bare greeting should never be classified by keyword search below (avoids
// the same kind of accidental substring collisions for any future keyword).
const isPureGreeting = /^(السلام عليكم|سلام عليكم|وعليكم السلام|صباح الخير|مساء الخير|مرحبا|مرحباً|هلا|اهلا|أهلا|أهلين|hi|hello|hey)[\s!.،,؟?]*$/i.test(text);

let service = 'Sales';
let client_intent = 'General Inquiry';

if (isPureGreeting) {
  service = item.selected_service_path || item.property_selected_service_path || 'Sales';
  client_intent = 'Greeting';
} else if (/سعر|تكلفة|عرض سعر|quotation|proposal|price|cost/.test(text) || hasStandaloneKam) {
  service = 'Sales';
  client_intent = 'Pricing Request';
} else if (/استشارة|consultation|احجز|موعد|meeting|schedule/.test(text)) {
  service = 'Sales';
  client_intent = 'Consultation Request';
} else if (/اقامة|إقامة|premium|residency/.test(text)) {
  service = 'Premium Residency';
  client_intent = 'Premium Residency';
} else if (/قوى|مدد|تأمينات|مقيم|بلدي|زكاة|ضريبة|حكومي|government|gosi|qiwa|mudad/.test(text)) {
  service = 'GRO';
  client_intent = 'GRO Support';
} else if (/موارد|توظيف|استقدام|hr|recruitment|عمالة/.test(text)) {
  service = 'HR & Recruitment';
  client_intent = 'Documents';
} else if (/سياحة|رحلات|tourism|trip|travel/.test(text)) {
  service = 'Tourism';
  client_intent = 'General Inquiry';
} else if (/عقار|مكتب|workspace|real estate|office/.test(text)) {
  service = 'Real Estate & Workspace';
  client_intent = 'General Inquiry';
} else if (/شركة|تأسيس|سجل|استثمار|مستثمر|llc|branch|فرع|رخصة|misa|commercial registration/.test(text)) {
  service = 'Company Setup';
  client_intent = 'Company Setup';
}

// The Knowledge Base is looked up by its own Service field, and two of the
// values this classifier produces have no rows there at all:
//   • 'Sales' — the catch-all for pricing, consultation and general inquiry,
//     which is every common message. Its content lives under 'Shared Services'.
//   • 'Real Estate & Workspace' — its content is the OFFICE-* rows, which are
//     filed under 'Company Setup'.
// Looking either one up returned zero rows, so the agent answered those
// messages with no knowledge context at all. Map them to where the rows
// actually are, and keep `service` untouched — the owner alert nodes read it.
const KB_SERVICE = {
  'Sales': 'Shared Services',
  'Real Estate & Workspace': 'Company Setup',
};
const kb_service = KB_SERVICE[service] || service;

return [
  {
    json: {
      ...item,
      service,
      kb_service,
      client_intent,
    },
  },
];

// Preserve client context from Detect Client Intent + inject KB text.
// Fixes context-loss that blanked message_text/phone/crm_page_id before the AI Agent.
const src = $('Detect Client Intent').all();
const ctx = (src[0] && src[0].json) ? src[0].json : {};
function str(v){ if(v===undefined||v===null) return ''; return String(v).trim(); }
function pick(o,keys){ for(const k of keys){ if(o && o[k]!==undefined && o[k]!==null && o[k]!=='') return o[k]; } return ''; }
function digits(v){ let t=str(v); const m={'٠':'0','١':'1','٢':'2','٣':'3','٤':'4','٥':'5','٦':'6','٧':'7','٨':'8','٩':'9','۰':'0','۱':'1','۲':'2','۳':'3','۴':'4','۵':'5','۶':'6','۷':'7','۸':'8','۹':'9'}; let o=''; for(const ch of t){ o += (m[ch]!==undefined ? m[ch] : ch); } return o.replace(/\s+/g,' ').trim(); }
function phoneOf(v){ let p=str(v).replace(/[^0-9]/g,''); if(p.indexOf('00')===0) p=p.slice(2); if(p.indexOf('0')===0 && p.length===10) p='966'+p.slice(1); if(p.indexOf('5')===0 && p.length===9) p='966'+p; return p; }
const kb=[];
for(const it of $input.all()){ const j=it.json||{}; for(const k of Object.keys(j)){ const v=j[k]; if(typeof v==='string' && v.trim().length>=15 && /answer|content|response|body|scenario|reply|summary|message|title|name|question|text/i.test(k)){ kb.push(v.trim()); } } }
const kbText = kb.join('\n\n').slice(0,3000);
const messageText = digits(pick(ctx,['message_text','normalized_text','user_message','client_message','property_last_whats_app_message','property_last_whatsapp_message']));
const phone = phoneOf(pick(ctx,['phone','recipient_phone','whatsapp_phone','property_whats_app','property_whats_app_phone']));
return [{ json: { ...ctx, crm_page_id: str(pick(ctx,['crm_page_id','page_id','id'])), crm_url: str(pick(ctx,['crm_url','url'])), phone: phone, recipient_phone: phone, message_text: messageText, normalized_text: messageText, user_message: messageText, client_message: messageText, knowledge_base_context: kbText, route_to_ai: true, send_direct_reply: false, route_reason: 'Send to AI Agent' } }];

// Build reply from AI output. Detect internal tags, strip them, sanitize WhatsApp markdown.
let aiText='';
try { aiText = $('AI Agent').first().json.output; } catch(e){}
let t = String(aiText||'').trim();
const orderCompleted = t.indexOf('#تم_الطلب') !== -1;
const needsHuman = t.indexOf('#تدخل_بشري') !== -1;
const consultationRequested = t.indexOf('#حجز_استشارة') !== -1;
t = t.split('\n').filter(function(line){ return line.indexOf('#تم_الطلب') === -1 && line.indexOf('#تدخل_بشري') === -1 && line.indexOf('#حجز_استشارة') === -1; }).join('\n');
t = t.replace(/\[([^\]]+)\]\(([^)]+)\)/g, '$1').replace(/\*\*(.+?)\*\*/g, '*$1*').replace(/^#{1,6}\s+/gm, '').replace(/`{1,3}/g, '').trim();
return [{ json: { text_body: t, reply_text: t, output: t, order_completed: orderCompleted, needs_human: needsHuman, consultation_requested: consultationRequested, debug_source: 'AI Agent output' } }];

